{
  "summary": "I treat the synthetic portfolio’s susceptibility scores as screening proxies, not measured flood depths or calibrated event frequencies, and retain restrained, reference-anchored assumptions pending local validation. The offer’s point is dry, but the common-tier buffer is wet; deep basements and critical plant matter, while protection, below-ground value and BI cover remain unconfirmed. The offer site was read using the stated 250 m buffer, which captures nearby mapped water despite dry point readings.",
  "parameters": [
    {
      "name": "depthScaleM",
      "reason": "The 0 to 1 terrain-and-river-proximity score is not measured depth, and only 12 of 24 named flood areas are flagged; I choose a midpoint between the proposals rather than treat either scale as calibrated.",
      "basis": "data_profile",
      "leans": "between",
      "value": 2.5
    },
    {
      "name": "fragility.informal_iron_sheet",
      "reason": "Informal iron-sheet buildings are 29.8% of buildings but only 0.3% of insured value; I retain the JRC reference multiplier because the synthetic class gives no condition evidence.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 1.5
    },
    {
      "name": "fragility.semi_permanent",
      "reason": "Semi-permanent buildings are 30.2% of buildings and 1.3% of insured value, but the profile gives no construction-condition detail to support a higher multiplier than the JRC reference.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 1.2
    },
    {
      "name": "fragility.permanent_masonry",
      "reason": "The JRC Africa residential curve is the stated damage basis, while the profile gives no masonry-specific performance evidence; I keep its reference multiplier.",
      "basis": "jrc_reference",
      "leans": "between",
      "value": 1
    },
    {
      "name": "fragility.concrete_rcc",
      "reason": "Concrete RCC represents 85.1% of insured value, but the synthetic profile supplies no flood-performance evidence; I retain the JRC reference multiplier and flag the commercial-curve mismatch.",
      "basis": "jrc_reference",
      "leans": "between",
      "value": 0.7
    },
    {
      "name": "cap.informal_iron_sheet",
      "reason": "The profile identifies 179 informal iron-sheet buildings but gives no evidence of their maximum damage share; I retain the reference cap rather than presume near-total loss.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 0.95
    },
    {
      "name": "cap.semi_permanent",
      "reason": "The 181 semi-permanent buildings have no stated repair or resilience characteristics, so the reference cap is more supportable than an increased cap.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 0.9
    },
    {
      "name": "cap.permanent_masonry",
      "reason": "The profile gives 156 permanent-masonry buildings but no evidence for a different maximum damage share; I use the reference cap.",
      "basis": "data_profile",
      "leans": "between",
      "value": 0.85
    },
    {
      "name": "cap.concrete_rcc",
      "reason": "RCC accounts for 85.1% of insured value, yet that concentration does not establish a higher maximum damage share; I retain its reference cap.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 0.8
    },
    {
      "name": "returnPeriods.extreme",
      "reason": "The score tiers have no fixed return periods, and the 5%-to-40% nested cuts are not observed event frequencies; I use the 10-year reference as an uncalibrated scenario assignment.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 10
    },
    {
      "name": "returnPeriods.severe",
      "reason": "The severe tier affects 51 buildings, but that count does not establish recurrence; I retain the 25-year reference, above the extreme assignment.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 25
    },
    {
      "name": "returnPeriods.moderate",
      "reason": "The moderate tier affects 110 buildings, which describes its footprint rather than frequency; I retain the 50-year reference between adjacent tiers.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 50
    },
    {
      "name": "returnPeriods.occasional",
      "reason": "The 174 buildings affected in this tier do not calibrate recurrence, so I keep the 100-year reference and its strict ordering.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 100
    },
    {
      "name": "returnPeriods.common",
      "reason": "The common tier is the widest footprint, affecting 259 buildings, and is defined as the rarest event; with no observed frequency, I retain the 250-year reference as a scenario assumption.",
      "basis": "data_profile",
      "leans": "optimist",
      "value": 250
    },
    {
      "name": "offer.bufferRadiusM",
      "reason": "The offer uses a stated 250 m search radius; its common-tier buffer depth is 0.310 m and nearest mapped water is about 148 m away, so I retain that radius pending footprint review.",
      "basis": "offer",
      "leans": "between",
      "value": 250
    },
    {
      "name": "offer.ingressThresholdM",
      "reason": "There are two basements with critical B1 plant, but barriers and non-return valves are unstated; I use the 0.1 m reference rather than infer protection or a lower trigger.",
      "basis": "offer",
      "leans": "optimist",
      "value": 0.1
    },
    {
      "name": "offer.basementDamageExtreme",
      "reason": "The ladder is steeper than the reference overall because critical plant is in B1 and pump backup is unknown; this first rung stays at the reference 0.15.",
      "basis": "offer",
      "leans": "between",
      "value": 0.15
    },
    {
      "name": "offer.basementDamageSevere",
      "reason": "The six below-ground equipment items support a modest step up from the prior rung, while the severe-tier point, buffer and ponding depths are zero.",
      "basis": "offer",
      "leans": "between",
      "value": 0.28
    },
    {
      "name": "offer.basementDamageModerate",
      "reason": "The 4.5 m-deep basement and critical plant support an increase over severe, although the moderate-tier mapped and ponding depths are zero.",
      "basis": "offer",
      "leans": "cautious",
      "value": 0.43
    },
    {
      "name": "offer.basementDamageOccasional",
      "reason": "The occasional tier marks drains overloaded and pump backup and barriers are unstated, supporting a larger step than the prior rung.",
      "basis": "offer",
      "leans": "cautious",
      "value": 0.62
    },
    {
      "name": "offer.basementDamageCommon",
      "reason": "The common tier has 0.310 m within the buffer and overloaded drains, alongside B1 plant; I set the highest rung above reference but below total loss.",
      "basis": "offer",
      "leans": "cautious",
      "value": 0.78
    },
    {
      "name": "offer.belowGroundShare",
      "reason": "The stated below-ground value is null, while the offer lists six equipment items and an underground fuel tank; the 0.1 fallback is judgement, not a measured share.",
      "basis": "judgement",
      "leans": "cautious",
      "value": 0.1
    },
    {
      "name": "offer.outageDaysExtreme",
      "reason": "BI cover is null, so this rung has no effect unless cover is confirmed; I retain the reference value.",
      "basis": "offer",
      "leans": "between",
      "value": 2
    },
    {
      "name": "offer.outageDaysSevere",
      "reason": "The offer does not state BI cover, so this rung has no current effect and remains at reference.",
      "basis": "offer",
      "leans": "between",
      "value": 5
    },
    {
      "name": "offer.outageDaysModerate",
      "reason": "BI cover is not stated, so this rung has no current effect; I retain its reference value rather than assume cover.",
      "basis": "offer",
      "leans": "between",
      "value": 10
    },
    {
      "name": "offer.outageDaysOccasional",
      "reason": "Critical plant is in B1, but the offer does not state BI cover; this rung therefore has no current effect and stays at reference.",
      "basis": "offer",
      "leans": "between",
      "value": 20
    },
    {
      "name": "offer.outageDaysCommon",
      "reason": "The offer leaves BI cover unstated, so this rung has no current effect; I use the reference value despite the basement plant exposure.",
      "basis": "offer",
      "leans": "between",
      "value": 40
    },
    {
      "name": "offer.uncertaintyLoading",
      "reason": "The drainage condition is only a placeholder and pump backup, barriers and valves are unstated; I choose a moderate increase over reference for these unmodelled uncertainties.",
      "basis": "offer",
      "leans": "cautious",
      "value": 0.15
    }
  ],
  "responses": [
    {
      "challengeId": "C1",
      "verdict": "accepted",
      "response": "Treat outputs as screening scenarios, not calibrated flood losses; the missed 12 of 24 named areas and proxy hazard support a restrained depth assumption and review against local observations."
    },
    {
      "challengeId": "C2",
      "verdict": "accepted",
      "response": "Use the file’s insured values as supplied, but flag the reported roughly tenfold formula discrepancy and request reconciliation before relying on portfolio totals."
    },
    {
      "challengeId": "C3",
      "verdict": "partly",
      "response": "Retain the stated 250 m radius because the common-tier buffer contains 0.310 m and mapped water is about 148 m away; disclose that this signal is nearby water, not point flooding, and request footprint and coordinate checks."
    },
    {
      "challengeId": "C4",
      "verdict": "accepted",
      "response": "Use a cautious, rising basement ladder and a fallback below-ground share because two basements contain critical plant and equipment; request actual values and evidence of pump backup, barriers and valves."
    },
    {
      "challengeId": "C5",
      "verdict": "accepted",
      "response": "Retain the supplied JRC reference assumptions without treating them as commercial validation; flag the residential curve and RCC concentration and seek commercial vulnerability evidence."
    },
    {
      "challengeId": "C6",
      "verdict": "accepted",
      "response": "The offer’s overload flags begin at the 100-year tier against its stated 50-year drain design; treat that as the model trigger, not verified operational capacity, and request maintenance and pump-backup details."
    },
    {
      "challengeId": "C7",
      "verdict": "accepted",
      "response": "Do not use the 11-year history, which records no flood loss, to calibrate hazard or basement response; ask the broker to confirm that it is complete."
    },
    {
      "challengeId": "C8",
      "verdict": "accepted",
      "response": "Keep the reference-based fragility, caps and return periods as uncalibrated assumptions, with the selected depth scale tempered by proxy limitations; test sensitivity before relying on the loss curve."
    }
  ]
}
